        token.transferFrom(holder, spender, TRANSFER_AMOUNT);

        // State after first transfer
        uint256 afterFirstAllowance = token.allowance(holder, spender);
        uint256 afterFirstHolderBalance = token.balanceOf(holder);
        uint256 afterFirstSpenderBalance = token.balanceOf(spender);

