        vm.prank(spender);
        token.transferFrom(holder, spender, TRANSFER_AMOUNT);

        // Final state
        uint256 finalAllowance = token.allowance(holder, spender);
        uint256 finalHolderBalance = token.balanceOf(holder);
        uint256 finalSpenderBalance = token.balanceOf(spender);

