        assertEq(afterFirstAllowance, MAX_ALLOWANCE, "Allowance decreased after first transfer");
        assertEq(finalAllowance, MAX_ALLOWANCE, "Allowance decreased after second transfer");

        assertEq(
            afterFirstHolderBalance, 
            initialHolderBalance - TRANSFER_AMOUNT, 
            "Incorrect holder balance after first transfer"
