            finalHolderBalance, 
            initialHolderBalance - 2 * TRANSFER_AMOUNT, 
            "Incorrect holder balance after second transfer"
        );
        assertEq(
            finalSpenderBalance, 
            initialSpenderBalance + 2 * TRANSFER_AMOUNT, 
            "Incorrect spender balance after second transfer"
        );
    }
}
